data.content:
MSTest **does** have comparison assertions (MSTest 3.x+). Here's what you need:

## Comparison Assertions

```csharp
Assert.IsGreaterThan(lowerBound, actual);
Assert.IsLessThan(upperBound, actual);
Assert.IsInRange(actual, low, high);
```

## Example Tests for Your ScoreCalculator

```csharp
[TestClass]
public sealed class ScoreCalculatorTests
{
    private readonly ScoreCalculator _calc = new();

    [TestMethod]
    [DataRow(9, 10, 90.0)]
    [DataRow(10, 10, 100.0)]
    [DataRow(0, 10, 0.0)]
    public void CalculatePercentage_ValidInputs_ReturnsExpected(int correct, int total, double expected)
    {
        Assert.AreEqual(expected, _calc.CalculatePercentage(correct, total));
    }

    [TestMethod]
    public void CalculatePercentage_ZeroTotal_Throws()
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(() => _calc.CalculatePercentage(5, 0));
    }

    [TestMethod]
    public void CalculatePercentage_CorrectGreaterThanTotal_Throws()
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(() => _calc.CalculatePercentage(11, 10));
    }

    [TestMethod]
    public void NormalizeScore_ResultAlwaysInRange()
    {
        var result = _calc.NormalizeScore(75, 200);

        Assert.IsInRange(result, 0.0, 100.0);
    }

    [TestMethod]
    public void NormalizeScore_ExceedsMax_CapsAt100()
    {
        var result = _calc.NormalizeScore(150, 100);

        Assert.AreEqual(100.0, result);
        Assert.IsLessThan(101.0, result); // never exceeds 100
    }

    [TestMethod]
    [DataRow(90.0, "A")]
    [DataRow(89.99, "B")]
    [DataRow(80.0, "B")]
    [DataRow(70.0, "C")]
    [DataRow(60.0, "D")]
    [DataRow(59.99, "F")]
    public void GetGrade_BoundaryValues_ReturnsCorrectGrade(double percentage, string expected)
    {
        Assert.AreEqual(expected, _calc.GetGrade(percentage));
    }

    [TestMethod]
    public void CalculatePercentage_PartialScore_IsGreaterThanZero()
    {
        var result = _calc.CalculatePercentage(1, 10);

        Assert.IsGreaterThan(0.0, result);
    }
}
```

## Key Takeaways

| Scenario | Assertion |
|----------|-----------|
| Value above a bound | `Assert.IsGreaterThan(lowerBound, actual)` |
| Value below a bound | `Assert.IsLessThan(upperBound, actual)` |
| Value within [low, high] | `Assert.IsInRange(actual, low, high)` |
| Exact boundary match | `Assert.AreEqual(expected, actual)` |
| Invalid input throws | `Assert.ThrowsExactly<T>(() => ...)` |

These assertions produce clear failure messages (e.g., "Expected value to be greater than 0.0, but was -5.0") compared to a generic `Assert.IsTrue(result > 0)`.
